   or (p_details ? 'roaster' and btrim(p_details->>'roaster') is distinct from oldcoffee.roaster)
   or (p_details ? 'release_label' and nullif(btrim(p_details->>'release_label'),'') is distinct from oldcoffee.release_label) then
